package actionbroker

import (
	"bytes"
	"encoding/hex"
	"encoding/json"
	"errors"
	"os"
	"testing"
)

// These fixtures mirror the field names, enum spellings, null behavior, and
// declaration order of action-broker-core's serde ActionRequest and
// ActionResponse types. They are intentionally fixed rather than generated by
// this Go implementation so wire drift is visible in review.
func TestRustCompatibleGoldenRequestAndResponse(t *testing.T) {
	requestJSON := readGolden(t, "testdata/read-file-request-v1.json")
	var request ActionRequest
	if err := decodeStrict(requestJSON, &request); err != nil {
		t.Fatalf("decode golden request: %v", err)
	}
	if err := request.validate(); err != nil {
		t.Fatalf("validate golden request: %v", err)
	}
	encodedRequest, err := json.Marshal(request)
	if err != nil {
		t.Fatalf("marshal golden request: %v", err)
	}
	if !bytes.Equal(encodedRequest, requestJSON) {
		t.Fatalf("request wire drift\n got: %s\nwant: %s", encodedRequest, requestJSON)
	}

	responseJSON := readGolden(t, "testdata/read-file-response-v1.json")
	var response ActionResponse
	if err := decodeStrict(responseJSON, &response); err != nil {
		t.Fatalf("decode golden response: %v", err)
	}
	if err := response.validateFor(request); err != nil {
		t.Fatalf("validate golden response: %v", err)
	}
	encodedResponse, err := json.Marshal(response)
	if err != nil {
		t.Fatalf("marshal golden response: %v", err)
	}
	if !bytes.Equal(encodedResponse, responseJSON) {
		t.Fatalf("response wire drift\n got: %s\nwant: %s", encodedResponse, responseJSON)
	}
}

func TestGoldenBigEndianFramePrefixAndBoundaries(t *testing.T) {
	payload := readGolden(t, "testdata/read-file-request-v1.json")
	prefixHex := readGolden(t, "testdata/read-file-request-v1.frame-prefix.hex")
	wantPrefix := make([]byte, 4)
	if _, err := hex.Decode(wantPrefix, prefixHex); err != nil {
		t.Fatalf("decode golden frame prefix: %v", err)
	}

	var framed bytes.Buffer
	if err := writeFrame(&framed, payload); err != nil {
		t.Fatalf("write golden frame: %v", err)
	}
	if !bytes.Equal(framed.Bytes()[:4], wantPrefix) {
		t.Fatalf("frame prefix drift: got %x want %x", framed.Bytes()[:4], wantPrefix)
	}
	decoded, err := readFrame(bytes.NewReader(framed.Bytes()))
	if err != nil {
		t.Fatalf("read golden frame: %v", err)
	}
	if !bytes.Equal(decoded, payload) {
		t.Fatal("framed payload changed during round-trip")
	}

	maximum := bytes.Repeat([]byte{'x'}, int(MaxFrameSize))
	if err := writeFrame(&bytes.Buffer{}, maximum); err != nil {
		t.Fatalf("maximum-size frame was rejected: %v", err)
	}
	tooLarge := append(maximum, 'x')
	err = writeFrame(&bytes.Buffer{}, tooLarge)
	var clientError *ClientError
	if !errors.As(err, &clientError) || clientError.Code != ErrorFrameTooLarge {
		t.Fatalf("oversized frame was not rejected with ErrorFrameTooLarge: %T %v", err, err)
	}
}

func readGolden(t *testing.T, path string) []byte {
	t.Helper()
	contents, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read %s: %v", path, err)
	}
	return bytes.TrimSpace(contents)
}
